// MainB.java
class Hewan {
    String nama;
    String suara;

    String bunyi() {
        return nama + " berkata " + suara;
    }
}

public class MainB {
    public static void main(String[] args) {
        Hewan h = new Hewan();
        h.nama = "Kucing";
        h.suara = "meong";
        System.out.println(h.bunyi());
    }
}

kasus.kode:
Hewan h = new Hewan();
h.nama = "Kucing";
h.suara = "meong";
sama("Kucing berkata meong meong meong", h.bunyi(3));
sama("Kucing berkata meong", h.bunyi(1));

Hewan h = new Hewan();
h.nama = "Kucing";
h.suara = "meong";
sama("Kucing diam", h.bunyi(0));
sama("Kucing diam", h.bunyi(-2));

Hewan h = new Hewan();
h.nama = "Ayam";
h.suara = "kukuruyuk";
sama("Ayam berkata kukuruyuk", h.bunyi());

Hewan a = new Hewan();
a.nama = "Kucing";
a.suara = "meong";
